"""Character direction first; current players and supporting records follow."""
from pathlib import Path
from html import escape as e
import json
from readability import render_readability


def render_agents():
    root = Path(__file__).resolve().parents[3]
    packs = {name: json.loads((root / f'apps/lab/lib/assets/generated/{name}.json').read_text())['assets']
             for name in ['loopforge', 'loopforge-console', 'loopforge-supervisors', 'loopforge-focused']}

    def pic(pack, key, label):
        variants = packs[pack][key]['variants']
        first = variants[0]
        sources = ', '.join(f'{v["src"]} {v["width"]}w' for v in variants)
        return f'<figure><a href="{variants[-1]["src"]}" target="_blank" rel="noopener"><img src="{first["src"]}" srcset="{sources}" sizes="(max-width:700px) 90vw, 520px" width="{first["width"]}" height="{first["height"]}" loading="lazy" decoding="async" alt="{e(label)}"></a><figcaption>{e(label)} · original concept reference</figcaption></figure>'

    out = ['''<header class="section-head"><span class="kicker">Agents · demonstrated Day1 and current review</span><h2 id="current-visual-milestone-approved-day-1">Current visual milestone — approved Day 1</h2><p>The owner has approved the demonstrated Day 1 slice: the arrival through Lobby and Security, the Conveyor tutorial and staffed line, the departure, and the night entrance. The approval belongs to the published R10 demonstration. Later source corrections need their own actual review.</p><p>The current visual work preserves the approved cast, machinery and industrial reference family. It addresses concrete reading and framing problems in the running scene: cards covering heads, a picture that changes height when words appear, and a departure camera obstructed by the facade. Keep the existing model players, motion records and original references below as working resources. A new model, palette or sheet revision is not required to solve those layout defects.</p><p><a href="/stepanoskin/loopforge/play/scene-studies">Play the Day 1 scene</a> · <a href="/stepanoskin/loopforge/design#model-briefs">Character and motion resources</a> · <a href="/stepanoskin/loopforge/design#dramaturgy">Character dramaturgy</a></p></header>''', render_readability(), '<section aria-labelledby="agents-rendered-assets"><h3 id="agents-rendered-assets">Rendered cast, materials and equipment</h3><h4 id="identity-at-the-size-of-the-action">Identity at the size of the action</h4><div class="table-scroll" tabindex="0" role="region" aria-label="Comparison table"><table><thead><tr><th scope="col">Subject</th><th scope="col">Current identity to preserve</th><th scope="col">What the Day1 evidence establishes</th></tr></thead><tbody><tr><td>Workers</td><td>An industrial blue family, exposed mechanical joints and distinct individual silhouettes. Bob’s paired circular lenses and compact body are strong cues.</td><td>Selected room frames retain blue bodies and recognizable head shapes. Every worker’s full motion bank and fine contacts have not been certified by this review.</td></tr><tr><td>LIMEN</td><td>Broad layered steel armour over dark mechanisms, with asymmetric cyan equipment.</td><td>The rescue and checkpoint views retain his mass and equipment colour. Speech placement can hide the skull and upper-body acting.</td></tr><tr><td>STILETTO</td><td>Tall slender black body, long twin tools and approved red upper-body identification.</td><td>These cues remain distinct beside the blue worker at the conveyor. Her small face/visor cannot carry identity when covered or viewed from behind.</td></tr><tr><td>CATHEXIS</td><td>Approved 100% ivory paint strength, dress/crown outline and 1.3× worker neutral-body height.</td><td>Preserve the existing approval and character player. She is not assessed in the captured Day1 slice.</td></tr></tbody></table></div><h4 id="working-objects-and-construction">Working objects and construction</h4><p><strong>Lobby</strong> carries the paperwork side of the factory through desk/terminal/lamp assemblies, forms and notices, and its relation to the entrance. Keep useful quiet space behind bodies and movement. Additional paper, wear and sign surfaces are optional refinements when a shot needs them; reproducing every detail in the original illustration is not a completion criterion.</p><p><strong>Security</strong> is a legible threshold: the admission portal, desks and lanes support the relationship between LIMEN and the arriving workers. Preserve the selected pale floor and current compact room authority. Older room illustrations supply mechanical construction and material lineage, not a requirement to copy their dimensions or darkness. Cards, hands, scanner targets and queues need separate close action evidence.</p><p><strong>Conveyor</strong> shows an intake, wash housing, belt, press portal, work pads and controls. The brain and press platen are visible in selected action frames. Keep moving parts, control targets and workpiece support separate from decorative housings. A completed production event is not proof that a hand pressed the correct control or that a workpiece cleared the machine throughout its motion.</p><p><strong>Entrance and departure</strong> retain the original sign/lintel/skull identity. Preserve the facade and authoritative actor paths. Authored southern story views use the selected sectioned-wall convention; they are not physical operational CCTV mounts. A camera passing into foreground ornament is a view defect, not a request for denser facade geometry.</p><h4 id="asset-delivery-interface">Asset delivery interface</h4><p>Every changed asset must identify its approved reference, source and optimized hashes, coordinate/scale convention, bounds, material/texture dependencies, rig/clip compatibility and semantic attachment points. Distinguish the detailed source, any delivered detail variants and the variants actually selected in the scene. Preserve identity-bearing head shapes, hands and tools when reducing detail. Availability of a variant is not evidence that its contact or scene-performance gate passed.</p><p>Animator owns the complete performed interaction; 3D supplies the usable body/prop interface.</p><p>The current review establishes no required mesh or material rebuild. Housing contrast and Lobby dressing remain optional refinements; motion, contact and performance require their own scene evidence.</p><figure><a href="/loopforge-dev-blog/media/2026-10-25-day-one/r10-wash-221s.png"><img src="/loopforge-dev-blog/media/2026-10-25-day-one/r10-wash-221s.png" width="1280" height="720" alt="Bob&#x27;s blue body and STILETTO&#x27;s black and red silhouette beside the wash housing and visible workpiece." loading="lazy" decoding="async"></a><figcaption>Actual approved R10, factory clock08:01:37 (video221s). Bob and STILETTO stand beside the wash housing and visible workpiece. This sampled frame does not establish hand contact or machine motion. Capture: Producer-operated studio browser; frame extracted by Animator.</figcaption></figure><figure><a href="/loopforge-dev-blog/media/2026-10-25-day-one/r10-forge-contact-287s.png"><img src="/loopforge-dev-blog/media/2026-10-25-day-one/r10-forge-contact-287s.png" width="1280" height="720" alt="Bob leaning toward the Forge console beside STILETTO and the visible press assembly." loading="lazy" decoding="async"></a><figcaption>Actual approved R10, factory clock08:01:56 (video287s). Bob leans toward the Forge console beside STILETTO; the press assembly is visible. Precise palm contact, timing and clearance remain unverified. Capture: Producer-operated studio browser; frame extracted by Animator.</figcaption></figure></section>',
    '''<div class="section-divider"></div><h3>Current models &amp; motion players</h3>
    <p>Inspect the existing assets, approved motions and fitted equipment. LIMEN and STILETTO show the accepted colour treatments; CATHEXIS retains her distinct ivory treatment.</p><div class="cast-player-list">''']
    current = [
        ('Worker 01', '/stepanoskin/loopforge/play/asset-review/worker', '19 approved motions · articulated hands', 'WORKER_MOTION_REVIEW.md'),
        ('LIMEN', '/stepanoskin/loopforge/play/agent-test/limen', '17 new source motions · cyan emitter · approved assembly', 'LIMEN_MESHY_REVIEW.md'),
        ('STILETTO', '/stepanoskin/loopforge/play/asset-review/stiletto', 'Twin blades or welders · red visor · motion bank', 'STILETTO_MOTION_REVIEW.md'),
        ('CATHEXIS', '/stepanoskin/loopforge/play/asset-review/cathexis', '4 approved motions · full or split Grace', 'CATHEXIS_MOTION_REVIEW.md'),
    ]
    for name, route, description, record in current:
        out.append(f'<div class="cast-player"><a href="{route}"><strong>{name} →</strong><span>{description}</span></a><a class="cast-record-link" href="/loopforge-design/production/{record}">Review record ↗</a></div>')
    out.append('''</div><p><a href="/stepanoskin/loopforge/design#model-briefs">Model briefs · reference art, Meshy prompts &amp; download kits →</a></p>
    <p>Character motives, narrative foundations and the ten-worker cast now have their own design chapter. <a href="/stepanoskin/loopforge/design#dramaturgy">Character dramaturgy and narrative design →</a></p>
    <h3 id="motion-day1-milestone">Character performance in the approved Day1 slice</h3><p><strong>Demonstrated and owner approved.</strong> The playable Day1 now connects the Lobby, Security and Conveyor through the opening confrontation, rescue, tutorial, later admissions, staffed work and departure. Ten distinct worker bodies appear alongside LIMEN and STILETTO. Named performances follow the same action history as movement, production and credential status. This is an approved playable slice, not a claim that the full campaign or every contact has been completed.</p><p>LIMEN&#x27;s blow, Sam&#x27;s approach to Bob and Ed&#x27;s move toward the dropped card establish different intentions. Preserve the complete sequence: strike and reaction; Sam&#x27;s help; Ed&#x27;s pickup, lift and stow; Sam&#x27;s release before Bob recovers; STILETTO arriving during the recovery. The player should understand those choices from the bodies and props as well as the dialogue.</p><p>The Day1 export records three production outputs and all twelve departures. Those results establish the recorded action history. They do not, by themselves, establish convincing hand contact, foot planting or continuous animation.</p><p><a href="/stepanoskin/loopforge/play/scene-studies">Play the Day1 scene</a>. The approved demonstration was published R10 on 25 October 2026 UTC; later candidate changes need their own verification.</p><figure><a href="/loopforge-dev-blog/media/2026-10-25-day-one/r10-help-and-card.png"><img src="/loopforge-dev-blog/media/2026-10-25-day-one/r10-help-and-card.png" width="1280" height="720" alt="Sam crouches beside folded Bob as Ed holds a card" loading="lazy" decoding="async"></a><figcaption>Actual approved R10 opening, factory clock08:00:26 (video76.4s). sam attends bob while ed holds the recovered card. This sampled frame does not establish contact quality or continuous motion. Capture: Producer-operated studio browser; frame extracted by Animator.</figcaption></figure><details><summary>Scene acting &amp; engine integration</summary><h3>Scene acting and engine integration</h3><p>The engine owns action timing, positions, reservations, custody and outcomes. Animation expresses that history through the actual character rig and named motion. A cue name, complete channel list or successful process condition is not an acting pass.</p><p>The original Worker 01&#x27;s nineteen corrected motions remain approved source material. Transfers to the ten distinct worker bodies need their own fit and scene review; source approval does not automatically approve each new shoulder, palm or stance. Current worker delivery includes portrait, floor and console detail tiers. Their existence is separate from contact, readability and performance acceptance in a particular shot.</p><p><strong>Implemented, with known review findings.</strong> The current scene blends named cues and completes a Day1 action sequence. Actual frame review found a persistent arms-out departure on the tall narrow worker, provisionally identified as Max, and an unclear fallen pose during Bob&#x27;s assistance. Some speech panels and the exit facade hide the acting. These are concrete follow-up findings against the approved slice, not a withdrawal of its approval. Exact rig causes and continuous contact remain to be verified.</p><p><strong>Deferred by the owner.</strong> Detailed Sam credential draw, presentation, return and carrier fitting are deferred. The temporary scene communicates credential status and preserves rescue, clearance and work participation. It does not claim that a physical card performance has been completed. Do not substitute a renamed idle or listening clip for that missing performance.</p><p>STILETTO&#x27;s source Idle reads as alert; source Alert reads as idle. Argument with blades reads as a threat, Reprimand as an attack. Preserve these established acting meanings when fitting targets and reactions.</p><p><a href="/loopforge-design/AGENT_CHARACTER_AND_ANIMATION_DIRECTION.md">Character and action direction</a> · <a href="/loopforge-design/production/SCENE_REHEARSALS.md">Action and speech architecture</a> · <a href="/stepanoskin/loopforge/design#dramaturgy">Character dramaturgy</a></p><h4>Staging and received speech</h4><p>The first morning count now continues through the complete shift. Current source binds speech, silent reactions and physical phases to the same scene clock. Normal story shots follow the encounter; the separate room-camera controls serve operational inspection. A room overview does not replace a close view of a hand, face or machine contact.</p><p>The next correction keeps the room footprint, pale Security floor, control roots and current identities. A stable picture area and separate reading space come before lens adjustments. Camera changes then frame the active worker, control and workpiece together; working desk views expose the actual register and sorting surfaces. The exit follows the real threshold and outside route instead of moving the camera through the facade.</p><p>Received speech remains a world event. Selected recruitment and paired-work replies need real approaches within the existing hearing rules. Quiet remarks may go unheard when no subsequent response depends on them. The successful shutdown reports and bob–sam closing exchange retain their actual listeners. No wider hearing radius or invented memory is used to repair a composition.</p><h4>Later-cohort static art and its limits</h4><p>The later cohort storyboards are completed static staging material, separate from implemented Day 1 play. Their final selected record carries 64 turns, 35 speech entries and 13 branches; three speech entries were explicitly amended and 32 retained from the Writer&#x27;s version. The boards distinguish attendance, consent, refusal, direct practice and ordinary production. The selected Wash action is a forward stroke, held stop and reset at the separate pedestal. It does not establish a reachable wheel, lift/turn mechanism, verified hand fit or measured throughput.</p><p>Final native pixel checks resolved a record plate covering Lou&#x27;s head and removed practice observers from the ordinary-production inset. Keep those bounded decisions with their exact source versions. Static board approval does not establish mobile readability, continuous performance, contact, navigation, hearing or runtime branch correctness. These remain staging resources for later integration, not a reason to keep polishing the approved Day 1 art.</p></details>
    <details><summary>Performance &amp; acceptance checks</summary><h3>What the next performance review must establish</h3><p>Review the complete action on the actual rig and in its intended scene: approach, contact, effort, release and aftermath. Keep body identity, stable support and visible custody. Measure unintended crossings and intended hand or tool contact, then judge the shot. Numerical clearance and a readable silhouette answer different questions.</p><p><strong>Proposed next correction.</strong> Start with the recorded arms-out walk: confirm the actor and selected clip, then compare the same gait phase in the delivered bank and runtime before changing either. For work, fit the real hand to the real console; an operator standing within the allowed process radius does not prove a press. Preserve the opening&#x27;s causal order while reviewing Bob&#x27;s held fall and Sam&#x27;s support.</p><p><strong>Evidence limit.</strong> The Animator review used selected decoded frame sequences from two actual recordings with a declared gap. It did not provide continuous video, complete contact coverage or a controlled performance comparison. The demonstrated ending and owner approval remain recorded; unrun tests remain unrun.</p><p>Keep silhouettes and useful contrast when optional shadows and bloom are off. Compare graphics settings on the same scene, then perform the longer acceptance check under controlled conditions. Neither a completed timing run nor an isolated close-up certifies the crowd or the whole factory.</p><figure><a href="/loopforge-dev-blog/media/2026-10-25-day-one/r10-forge-contact-287s.png"><img src="/loopforge-dev-blog/media/2026-10-25-day-one/r10-forge-contact-287s.png" width="1280" height="720" alt="Bob leans toward the forge console beside STILETTO and the lowered press" loading="lazy" decoding="async"></a><figcaption>Actual R10 Forge operation, factory clock08:01:56 (video287s). bob leans toward the console beside STILETTO. Precise palm contact remains unverified. Capture: Producer-operated studio browser; frame extracted by Animator.</figcaption></figure><p><a href="/loopforge-design/production/CHARACTER_REVIEW_STRUCTURE.md">Six review checks</a> · <a href="/loopforge-design/production/GRAPHICS_AND_PERFORMANCE.md">Graphics and performance evidence</a></p></details>
    <details><summary>Original character &amp; room references</summary>
    <p>These establish the existing identities. They are not revised sheets for the new palette proposal.</p><div class="agent-gallery">''')
    for pack, key, label in [
        ('loopforge-supervisors', 'thrum-conveyor', 'Worker reference · worn industrial bodies'),
        ('loopforge', 'limen', 'LIMEN · heavy armour and one cyan blade'),
        ('loopforge-console', 'stiletto-portrait', 'STILETTO · black chrome and twin tool arms'),
        ('loopforge', 'cathexis', 'CATHEXIS · porcelain, dress and crown'),
        ('loopforge', 'witch', 'RIVET WITCH · future cast'),
        ('loopforge', 'thrum', 'THRUM · future cast'),
        ('loopforge-supervisors', 'limen-security', 'Security · clerks, desks and queues'),
        ('loopforge-supervisors', 'stiletto-conveyor-success-2', 'Conveyor · staffed work cells'),
        ('loopforge-focused', 'lobby-room', 'Lobby · paperwork and worker claims'),
    ]:
        out.append(pic(pack, key, label))
    out.append('''</div><p>Historical room study: Security 18 × 16 m and Lobby 22 × 16 m. These earlier dimensions are not the current compact Day1 room specification; the Floor and Conveyor chapters describe the selected layout.</p>
    <p><a href="/loopforge-design/production/ROOM_ASSET_BRIEFS.md">Room assets &amp; Meshy briefs ↗</a> · <a href="/loopforge-design/AGENT_CHARACTER_AND_ANIMATION_DIRECTION.md">Character &amp; action direction ↗</a></p></details>
    <details><summary>Earlier engineering prototype · historical reference</summary>
    <p>The 12 October fixture uses rejected placeholder robots to exercise reservations, prop ownership and replay. Use the current players above for character review.</p><p><a href="/loopforge-design/production/AGENT_PRODUCTION_TEST.md">Engineering record ↗</a> · <a href="/stepanoskin/loopforge/play/agent-test">Legacy fixture ↗</a></p></details>''')
    return ''.join(out)
